public class Main {
    public static void main(String[] args) {
        System.out.println("=== StackOverflowError (deep recursion, no tail-call opt on JVM) ===");
        try {
            recurse(0);
            System.out.println("    no overflow : false");
        } catch (StackOverflowError e) {
            System.out.println("    StackOverflowError caught : true");
            System.out.println("    -> stack frames, NOT heap: enlarging -Xmx does not help");
        }

        System.out.println("=== OutOfMemoryError (array size exceeds VM limit, heap independent) ===");
        try {
            long[] huge = new long[Integer.MAX_VALUE];
            System.out.println("    allocated : true, length=" + huge.length);
        } catch (OutOfMemoryError e) {
            System.out.println("    OutOfMemoryError caught : true");
            System.out.println("    message : " + e.getMessage());
            System.out.println("    -> 2^31-1 longs is ~16 GiB, rejected before heap is even consulted");
        }

        System.out.println("=== the JVM survives a caught OutOfMemoryError ===");
        int alive = 0;
        for (int i = 0; i < 3; i++) alive += 1;
        System.out.println("    main thread still running : " + (alive == 3));
        System.out.println("    caught OOM is recoverable, but the heap state is usually unsafe");
    }

    static int recurse(int d) {
        return recurse(d + 1) + 1;
    }
}
